import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

function App() {
  // ⚠️ API KEY'İNİ BURAYA YAPIŞTIR
  const API_KEY = "BURAYA_GOOGLE_API_KEY_YAPISTIR"; 

  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]); 
  const [filtre, setFiltre] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  const [seciliMekan, setSeciliMekan] = useState(null); 
  const [listeAcik, setListeAcik] = useState(false);
  const [aktifResimIndex, setAktifResimIndex] = useState(0);

  // AI
  const [aiCevap, setAiCevap] = useState("");
  const [aiYukleniyor, setAiYukleniyor] = useState(false);
  const [aiDil, setAiDil] = useState("Türkçe");

  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(Array.isArray(data) ? data : []))
      .catch(err => console.error("Bağlantı Hatası:", err));
  }, []);

  // --- ROTA EKLE / ÇIKAR ---
  const favoriEkleCikar = (mekan) => {
    setFavoriler((prev) => {
      // ID'leri == ile karşılaştırıyoruz (sayı/yazı fark etmesin diye)
      const varMi = prev.some(item => item.id == mekan.id);

      if (varMi) {
        return prev.filter(item => item.id != mekan.id);
      } else {
        // Süreyi sayıya çevirip ekliyoruz
        return [...prev, { ...mekan, sure: parseInt(mekan.sure) || 0 }];
      }
    });
  };

  // --- DETAY AÇMA ---
  const detayAc = (mekan) => {
    // Resim listesi kontrolü
    const guvenliMekan = { 
      ...mekan, 
      resimler: (mekan.resimler && mekan.resimler.length > 0) ? mekan.resimler : ["https://via.placeholder.com/400"] 
    };
    setSeciliMekan(guvenliMekan); 
    setAktifResimIndex(0); 
    setAiCevap(""); 
  };

  const toplamSure = favoriler.reduce((toplam, m) => toplam + (parseInt(m.sure) || 0), 0);
  const saat = Math.floor(toplamSure / 60);
  const dakika = toplamSure % 60;

  const yapayZekayaSor = async (mekanAdi, bolge) => {
    if (!API_KEY || API_KEY.includes("BURAYA")) {
      setAiCevap("⚠️ Lütfen API Key'i kodun içine yapıştırın.");
      return;
    }
    setAiYukleniyor(true);
    setAiCevap(""); 
    try {
      const genAI = new GoogleGenerativeAI(API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-pro"});
      const prompt = `Sen Antalya rehberisin. "${mekanAdi}" (${bolge}) hakkında ${aiDil} dilinde 3 cümlelik bilgi ver.`;
      const result = await model.generateContent(prompt);
      const response = await result.response;
      setAiCevap(response.text());
    } catch (error) {
      setAiCevap("😔 Bağlantı hatası. API Key'i kontrol et.");
    } finally {
      setAiYukleniyor(false);
    }
  };

  const filtrelenmis = mekanlar.filter(m => {
    const katUygun = filtre === 'Hepsi' || m.kategori === filtre;
    const sureUygun = maxSure === '' || (parseInt(m.sure) || 0) <= parseInt(maxSure || 9999);
    return katUygun && sureUygun;
  });

  return (
    <div className="container">
      <style>{`
        body { font-family: 'Poppins', sans-serif; background-color: #f8f9fa; margin: 0; padding: 20px; }
        .header { text-align: center; margin-bottom: 30px; color: #1a4d6e; }
        .controls { display: flex; justify-content: center; gap: 10px; margin-bottom: 25px; flex-wrap: wrap; }

        .summary-bar { 
          background: #1a4d6e; color: white; padding: 15px 30px; 
          border-radius: 50px; display: flex; justify-content: space-around; 
          margin-bottom: 30px; font-weight: 600; cursor: pointer; user-select: none;
          box-shadow: 0 4px 15px rgba(26, 77, 110, 0.3); transition: transform 0.2s;
        }
        .summary-bar:active { transform: scale(0.95); }

        .grid { display: flex; flex-wrap: wrap; justify-content: center; gap: 25px; }

        .card { width: 280px; background: white; border-radius: 20px; overflow: hidden; box-shadow: 0 5px 15px rgba(0,0,0,0.05); display: flex; flex-direction: column; transition: all 0.3s ease; border: 2px solid transparent; box-sizing: border-box; }
        .card:hover { transform: translateY(-5px); border-color: #00c2cb; box-shadow: 0 10px 25px rgba(0, 194, 203, 0.15); }

        /* Tıklanabilir Alanlar Ayrıldı */
        .card-clickable { cursor: pointer; } 

        .card-image-container { height: 180px; position: relative; padding: 10px; }
        .card-img { width: 100%; height: 100%; object-fit: cover; border-radius: 15px; }
        .badge { position: absolute; top: 15px; right: 15px; background: rgba(0,0,0,0.6); color: white; padding: 4px 10px; border-radius: 8px; font-size: 11px; }
        .card-content { padding: 15px; flex-grow: 1; display: flex; flex-direction: column; justify-content: space-between; }

        .btn-action { 
          width: 100%; padding: 10px; border-radius: 20px; 
          border: 1px solid #1a4d6e; background: transparent; 
          color: #1a4d6e; font-weight: 600; cursor: pointer; 
          margin-top: 10px; display: flex; justify-content: center; align-items: center; gap: 5px; 
        }
        .btn-action:hover { background: #1a4d6e; color: white; }
        .btn-remove { border-color: #e74c3c; color: #e74c3c; }
        .btn-remove:hover { background: #e74c3c; color: white; }

        .modal-overlay { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.8); z-index: 1000; display: flex; justify-content: center; align-items: center; }
        .modal-content { background: white; padding: 25px; border-radius: 20px; max-width: 500px; width: 90%; text-align: center; max-height: 90vh; overflow-y: auto; }
        .close-btn { position: absolute; top: 15px; right: 15px; background: #f1f1f1; border: none; width: 30px; height: 30px; border-radius: 50%; cursor: pointer; font-weight: bold; }
        .main-gallery-img { width: 100%; height: 250px; object-fit: cover; border-radius: 15px; }
        .thumbnail-container { display: flex; gap: 10px; margin-top: 15px; overflow-x: auto; justify-content: center; padding-bottom: 5px;}
        .thumbnail-img { width: 60px; height: 40px; object-fit: cover; border-radius: 8px; cursor: pointer; opacity: 0.6; border: 2px solid transparent; }
        .thumbnail-img.active { opacity: 1; border-color: #00c2cb; transform: scale(1.1); }
        .ai-box { margin-top: 20px; background: #f0fdfa; padding: 15px; border-radius: 15px; border: 1px dashed #00c2cb; text-align: left; }
        .btn-ai { background: linear-gradient(45deg, #00c2cb, #1a4d6e); color: white; border: none; padding: 8px 20px; border-radius: 10px; cursor: pointer; font-weight: bold; }
      `}</style>

      <div className="header"><h1>🌴 Antalya Rota Asistanı</h1></div>

      <div className="controls">
        <input type="number" placeholder="Maks. Süre (dk)" value={maxSure} onChange={(e) => setMaxSure(e.target.value)} style={{padding: '10px 20px', borderRadius: '25px', border: '1px solid #ddd'}} />
        {['Hepsi', 'Tarih', 'Doğa', 'Yemek', 'Eğlence'].map(k => (
          <button key={k} onClick={() => setFiltre(k)} style={{padding: '8px 20px', borderRadius: '25px', border: 'none', cursor: 'pointer', background: filtre === k ? '#1a4d6e' : 'white', color: filtre === k ? 'white' : '#666', marginLeft: '5px'}}>{k}</button>
        ))}
      </div>

      <div className="summary-bar" onClick={() => setListeAcik(true)}>
        <span>🎒 Rotam: {favoriler.length} Yer</span>
        <span>⏱️ Toplam: {saat}sa {dakika}dk</span>
      </div>

      <div className="grid">
        {filtrelenmis.map(m => {
          const seciliMi = favoriler.some(f => f.id == m.id);
          const anaResim = (m.resimler && m.resimler.length > 0) ? m.resimler[0] : "https://via.placeholder.com/300";

          return (
            <div key={m.id} className="card">
              {/* TIKLANABİLİR BÖLGE 1: DETAY AÇAR */}
              <div className="card-clickable" onClick={() => detayAc(m)}>
                <div className="card-image-container">
                  <img src={anaResim} alt={m.ad} className="card-img" />
                  <span className="badge">{m.kategori}</span>
                </div>
                <div className="card-content" style={{paddingBottom: '0'}}>
                  <h3 style={{margin: '0 0 5px 0', color: '#1a4d6e', fontSize: '16px'}}>{m.ad}</h3>
                  <div style={{fontSize: '13px', color: '#7f8c8d', display: 'flex', justifyContent: 'space-between'}}>
                     <span>📍 {m.bolge}</span><span>⏳ {m.sure} dk</span>
                  </div>
                </div>
              </div>

              {/* TIKLANABİLİR BÖLGE 2: BUTON (AYRI) */}
              <div style={{padding: '15px', paddingTop: '0'}}>
                <button 
                  className={`btn-action ${seciliMi ? 'btn-remove' : ''}`} 
                  onClick={() => favoriEkleCikar(m)}
                >
                  {seciliMi ? 'Rotadan Çıkar ✕' : 'Rotaya Ekle ➜'}
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {seciliMekan && (
        <div className="modal-overlay" onClick={() => setSeciliMekan(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setSeciliMekan(null)}>✕</button>
            <img src={seciliMekan.resimler[aktifResimIndex]} className="main-gallery-img" alt="Mekan" />

            {seciliMekan.resimler.length > 1 && (
              <div className="thumbnail-container">
                {seciliMekan.resimler.map((resim, index) => (
                  <img key={index} src={resim} className={`thumbnail-img ${index === aktifResimIndex ? 'active' : ''}`} onClick={() => setAktifResimIndex(index)} />
                ))}
              </div>
            )}

            <h2 style={{color: '#1a4d6e', marginTop: '15px'}}>{seciliMekan.ad}</h2>
            <div style={{display:'flex', gap:'10px', justifyContent:'center', marginTop:'15px'}}>
               <select value={aiDil} onChange={(e) => setAiDil(e.target.value)} style={{padding:'5px', borderRadius:'10px'}}>
                  <option>Türkçe</option><option>İngilizce</option><option>Almanca</option>
               </select>
               <button className="btn-ai" onClick={() => yapayZekayaSor(seciliMekan.ad, seciliMekan.bolge)} disabled={aiYukleniyor}>
                 {aiYukleniyor ? "..." : "🤖 AI'a Sor"}
               </button>
            </div>
            {aiCevap && <div className="ai-box">{aiCevap}</div>}
          </div>
        </div>
      )}

      {listeAcik && (
        <div className="modal-overlay" onClick={() => setListeAcik(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setListeAcik(false)}>✕</button>
            <h3>🎒 Rotan</h3>
            {favoriler.map(fav => (
              <div key={fav.id} style={{padding: '10px', borderBottom: '1px solid #eee', display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
                <div><strong>{fav.ad}</strong><div style={{fontSize:'12px', color:'#777'}}>{fav.sure} dk</div></div>
                <button onClick={() => favoriEkleCikar(fav)} style={{background:'#ffebee', color:'red', border:'none', borderRadius:'50%', width:'25px', height:'25px', cursor:'pointer'}}>✕</button>
              </div>
            ))}
            {favoriler.length > 0 && <p style={{fontWeight:'bold', color:'green', marginTop:'10px'}}>Toplam: {saat} sa {dakika} dk</p>}
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
